<?php
namespace App\Http\Controllers;
use App\Models\Department;use App\Models\FounderInterestRequest;use Illuminate\Contracts\View\View;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
class FounderProgramController extends Controller {public function show():View{return view('founder-program.show',['departments'=>Department::orderBy('name')->get()]);}public function store(Request $request):RedirectResponse{$data=$request->validate(['business_name'=>['required','string','max:191'],'contact_name'=>['required','string','max:120'],'email'=>['required','email:rfc','max:191'],'phone'=>['nullable','string','max:40'],'relationship_role'=>['required',Rule::in(['owner','manager','marketing','community','other'])],'department'=>['required','string','max:80'],'website'=>['nullable','url:http,https','max:191'],'message'=>['required','string','min:30','max:2000'],'privacy'=>['accepted'],'fax_number'=>['nullable','max:0']],['privacy.accepted'=>'Debes aceptar el tratamiento de datos para responder la solicitud.']);unset($data['privacy'],$data['fax_number']);$data+=['public_id'=>(string)Str::uuid(),'privacy_accepted_at'=>now(),'status'=>'new'];FounderInterestRequest::create($data);return back()->with('founder_request_status','Recibimos tu solicitud. La revisaremos antes de establecer cualquier relación o publicación.');}}
